entries[68775] = { ["name"] = "Flüchtiger Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n+3 Stärke\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Stärke\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie des Kataklysmus\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[68776] = { ["name"] = "Lebhafter Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n+3 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Beweglichkeit\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie des Kataklysmus\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[68777] = { ["name"] = "Leuchtender Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n+3 Intelligenz\nErhöht Eure Tempowertung um + 2.\n\nPrismatischer Sockel\nSockelbonus: + 1 Intelligenz\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie des Kataklysmus\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
