entries[68781] = { ["name"] = "Vorlage: Agiler Irrlichtdiamant", ["text"] = "Benutzen: Lehrt Euch das Schleifen eines agilen Irrlichtdiamanten.\nBenötigt Juwelierskunst des Kataklysmus\n(40)\nVerkaufspreis:\nAgiler Irrlichtdiamant\n+ 6 Beweglichkeit und um 3% erhöhter kritischer Effekt\n\"Passt nur in einen Sockel der Kategorie Meta.\"\nVerkaufspreis:\nBenötigt Irrlichtdiamant" }
entries[68782] = { ["name"] = "Vorlage: Widerscheinender Irrlichtdiamant", ["text"] = "Benutzen: Lehrt Euch das Schleifen eines widerscheinenden Irrlichtdiamanten.\nBenötigt Juwelierskunst des Kataklysmus\n(40)\nVerkaufspreis:\nWiderscheinender Irrlichtdiamant\n+ 6 Stärke und um 3% erhöhter kritischer Effekt\n\"Passt nur in einen Sockel der Kategorie Meta.\"\nVerkaufspreis:\nBenötigt Irrlichtdiamant" }
entries[68783] = { ["name"] = "Vorlage: Brennender Irrlichtdiamant", ["text"] = "Benutzen: Lehrt Euch das Schleifen eines brennenden Irrlichtdiamanten.\nBenötigt Juwelierskunst des Kataklysmus\n(40)\nVerkaufspreis:\nBrennender Irrlichtdiamant\n+ 6 Intelligenz und um 3% erhöhter kritischer Effekt\n\"Passt nur in einen Sockel der Kategorie Meta.\"\nVerkaufspreis:\nBenötigt Irrlichtdiamant" }
entries[68784] = { ["name"] = "Armschiene - Beweglichkeit", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Beweglichkeit um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[68785] = { ["name"] = "Armschiene - Erhebliche Stärke", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Stärke um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[68786] = { ["name"] = "Armschiene - Mächtige Intelligenz", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Intelligenz um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[68787] = { ["name"] = "Formel: Armschiene - Beweglichkeit", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Beweglichkeit' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Beweglichkeit um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (65)\nVerkaufspreis:" }
entries[68788] = { ["name"] = "Formel: Armschiene - Erhebliche Stärke", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Erhebliche Stärke' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Stärke um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (65)\nVerkaufspreis:" }
entries[68789] = { ["name"] = "Formel: Armschiene - Mächtige Intelligenz", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Mächtige Intelligenz' durchführt.\nArmschienen dauerhaft verzaubern, sodass die Intelligenz um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (65)\nVerkaufspreis:" }
entries[68793] = { ["name"] = "Ausgebrannte Glyphe", ["text"] = "Klassen: Todesritter\n\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[68795] = { ["name"] = "Stendels Ruin", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser riesige, aufgeblähte Wels ist Stendel jahrelang entkommen und mit Narben übersät. Er scheint fast zu grinsen.\"\n<Zum Öffnen rechtsklicken>" }
entries[68796] = { ["name"] = "Verstärkte Angelschnur", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ersetzt die Angelschnur Eurer Angelrute mit einer etwas festeren, wodurch die Angelfertigkeit dauerhaft um 1 erhöht wird. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:" }
entries[68797] = { ["name"] = "Stendels Ehering", ["text"] = "Wird beim Anlegen gebunden\nFinger\nErhöht Eure kritische Trefferwertung um + 3.\nVerkaufspreis:" }
entries[68806] = { ["name"] = "Kalythas Spukmedaillon", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ladet den Geist von Kalytha ein, von Euch Besitz zu ergreifen. (15 Min Abklingzeit)" }
entries[68808] = { ["name"] = "Ruhestein des Helden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teleportiert Euch sofort zum \"Zum Goldenen Fass\" in Sturmwind. Kann nur einmal benutzt werden.\n\"Vergesst nicht, Euren eigenen Ruhestein zu binden, wenn Ihr in Sturmwind seid!\"" }
entries[68809] = { ["name"] = "Ruhestein des Veteranen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teleportiert Euch sofort zum Tal der Weisheit in Orgrimmar. Kann nur einmal benutzt werden.\n\"Vergesst nicht, Euren eigenen Ruhestein zu binden, wenn Ihr in Orgrimmar seid!\"" }
entries[68812] = { ["name"] = "Hornissenstichband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[68813] = { ["name"] = "Ranzen mit frisch gepflückten Kräutern", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält eine Auswahl von 20 zufälligen Cataclysm-Kräutern\"\n<Zum Öffnen rechtsklicken>" }
entries[68820] = { ["name"] = "Stotterspritters Blaupausen", ["text"] = "Questgegenstand\n\"Die Blaupausen enthalten eine detaillierte Anleitung zum Bau der Silberblitz X-831.\"" }
entries[68823] = { ["name"] = "Gepanzerter Razzashiraptor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren gepanzerten Razzashiraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die reinrassigen königlichen Raptoren von Zul'Gurub sind im Schlingendorntal zu einer Seltenheit geworden. Wenn die Gurubashi jemand anderen als einen Troll auf einem ihrer geliebten Tiere erblicken, steigern sie sich in einen Blutrausch.\"\nBeute von:\nBlutfürst Mandokir\nZone:\nZul'Gurub" }
entries[68824] = { ["name"] = "Schneller zulianischer Panther", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen schnellen zulianischen Panther oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Pantherfangzähne sind schon seit langer Zeit bei den Dschungeltrollen begehrt. Sie werden in Ritualen oder als Zutaten von Mojos verwendet.\"\nBeute von:\nHohepriesterin Kilnara\nZone:\nZul'Gurub" }
entries[68825] = { ["name"] = "Drachenfalke der Amani", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachenfalken der Amani oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Drachenfalken, die aus der Versklavung durch Trolle befreit wurden, gehören zu den treuesten ihrer Art.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[68833] = { ["name"] = "Pantherjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Pantherjunges beschwören oder wieder freigeben.\n80 ( 80)" }
entries[68837] = { ["name"] = "Dämonensaat", ["text"] = "Questgegenstand\n\"Leuchtet mit dämonischer Energie.\"" }
entries[68840] = { ["name"] = "Landros Lichling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Landros Lichling beschwören oder wieder freigeben.\n80 ( 80)" }
entries[68841] = { ["name"] = "Nachtsäblerjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Nachtsäblerjunges beschwören oder wieder freigeben.\n80 ( 80)" }
entries[68890] = { ["name"] = "Doppelpack Papierdrachen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lasst mit Eurem Waisenkind einen Papierdrachen steigen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[68915] = { ["name"] = "Waagschalen des Lebens", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Waagschalen des Lebens (1)\nSchmuck\n+6 Ausdauer\nAnlegen: Speichert bis zu 511 zusätzliche Gesundheit aus Zaubern, die Euch über Eure maximale Gesundheit hinaus heilen.\nBenutzen: Gibt sofort alle auf den Waagschalen des Lebens angesammelte Gesundheit als Selbstheilung frei. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[68925] = { ["name"] = "Wechselimpulsblitzkondensator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Wechselimpulsblitzkondensator (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Ihr erhaltet eine elektrische Aufladung, wann immer Ihr einen kritischen Zaubertreffer erzielt, was eine Chance verleiht, einen 'Blitzschlag' abzufeuern, der pro gesammelter 'Elektrischer Aufladung' ( 9 * 0.875) bis ( 9 * 1.125) Schaden verursacht. Ihr könnt nicht mehr als 10 'Elektrische Aufladungen' ansammeln und könnt nicht mehr als einmal alle 2,5 Sek. eine erhalten. (2.5s Abklingzeit)\nVerkaufspreis:" }
entries[68926] = { ["name"] = "Fänge des Schicksals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Fänge des Schicksals (1)\nSchmuck\n+4 Intelligenz\nBenutzen: Die nächsten 10 Zauber, die innerhalb der nächsten 20 Sek. gewirkt werden, verringern die Kosten Eurer Heilig- und Naturzauber um 1 . Bis zu 10-mal stapelbar. (900ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68927] = { ["name"] = "Der Hungerleider", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Der Hungerleider (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, Euer Tempo 15 Sek. lang um 22 zu erhöhen. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[68937] = { ["name"] = "Düsterhammers Stiefel", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Stiefel haben schon bessere Tage gesehen.\"" }
entries[68955] = { ["name"] = "Totem von Tortolla", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Umhüllt Euch 10 Sek. lang mit einem undurchdringlichen Panzer. (20 Sek. Abklingzeit)" }
entries[68972] = { ["name"] = "Apparat von Khaz'goroth", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Apparat von Khaz'goroth (1)\nSchmuck\n+4 Stärke\nAnlegen: Eure kritischen Nahkampftreffer gewähren Euch Titanische Kraft, mit der Ihr diesen Apparat betreiben könnt. Die Titanische Kraft ist bis zu 5-mal stapelbar und hält 30 Sek. lang an.\nBenutzen: Zehrt sämtliche Titanische Kraft auf, um Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft pro angesammelter Titanischer Kraft um 5 zu erhöhen. Hält 15 Sek. lang an. Der Apparat wird immer den höchsten dieser drei Werte auswählen. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68981] = { ["name"] = "Spinnenseidenspindel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Spinnenseidenspindel (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Nahkampfangriffe, die Eure Gesundheit unter 35% fallenlassen, verleihen Euch einen Schutzschild, der 30 Sek. lang 437 Schaden absorbiert. Kann nicht öfter als ein Mal pro Minute auftreten. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[68982] = { ["name"] = "Nekromantischer Fokus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Nekromantischer Fokus (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Jedes Mal, wenn Eure regelmäßigen Zauber Schaden verursachen, wird Eure Meisterschaft 10 Sek. lang um 1 erhöht. Bis zu 10-mal stapelbar.\nVerkaufspreis:" }
entries[68983] = { ["name"] = "Auge der lodernden Kraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Auge der lodernden Kraft (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, das am schwersten verletzte nahe Gruppenmitglied um 87 zu heilen. (Procchance: 10%, 45s Abklingzeit)\nVerkaufspreis:" }
entries[68994] = { ["name"] = "Matrixrestabilisator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Matrixrestabilisator (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft (je nachdem, welcher Wert derzeit am höchsten ist) 30 Sek. lang um 18 zu erhöhen. (Procchance: 20%, 1.75Min. Abklingzeit)\nVerkaufspreis:" }
entries[68995] = { ["name"] = "Gefäß der Beschleunigung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Gefäß der Beschleunigung (1)\nSchmuck\n+4 Stärke\nAnlegen: Erhöht jedes Mal, wenn Ihr einen kritischen Nahkampftreffer erzielt, den kritischen Trefferwert 20 Sek. lang um 1 . Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[68996] = { ["name"] = "Hinrichtungsaufschub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Hinrichtungsaufschub (1)\nSchmuck\n+ 6 Ausweichen\nBenutzen: Absorbiert 20% des eintreffenden Schadens, bis zu 54 Schaden insgesamt. Wenn der Effekt endet, erleidet Ihr 10 Sek. lang alle 2 Sek. 8% des absorbierten Schadens. Hält 30 Sek. lang an. (2 Min Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
entries[68997] = { ["name"] = "Stab des Wächters", ["text"] = "Questgegenstand\nBenutzen: In den Aschehaufen platzieren, um Galenges zu beschwören." }
entries[68998] = { ["name"] = "Rune von Zeth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Rune von Zeth (1)\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nBenutzen: Erhöht Eure Intelligenz 15 Sek. lang um 13 . (1 Min Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
entries[69000] = { ["name"] = "Feurige Quintessenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Feurige Quintessenz (1)\nSchmuck\n+ 6 Vielseitigkeit\nBenutzen: Erhöht Eure Intelligenz 25 Sek. lang um 13 . (1 Min, 30 Sek. Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
entries[69001] = { ["name"] = "Uraltes versteinertes Samenkorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Uraltes versteinertes Samenkorn (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Erhöht Eure Beweglichkeit 15 Sek. lang um 13 . (1 Min Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
entries[69002] = { ["name"] = "Essenz der ewigen Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Essenz der ewigen Flamme (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Erhöht Eure Stärke 15 Sek. lang um 13 . (1 Min Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
