entries[69109] = { ["name"] = "Waagschalen des Lebens", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Waagschalen des Lebens (1)\nSchmuck\n+6 Ausdauer\nAnlegen: Speichert bis zu 170 zusätzliche Gesundheit aus Zaubern, die Euch über Eure maximale Gesundheit hinaus heilen.\nBenutzen: Gibt sofort alle auf den Waagschalen des Lebens angesammelte Gesundheit als Selbstheilung frei. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[69110] = { ["name"] = "Wechselimpulsblitzkondensator", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Wechselimpulsblitzkondensator (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Ihr erhaltet eine elektrische Aufladung, wann immer Ihr einen kritischen Zaubertreffer erzielt, was eine Chance verleiht, einen 'Blitzschlag' abzufeuern, der pro gesammelter 'Elektrischer Aufladung' ( 31 * 0.875) bis ( 31 * 1.125) Schaden verursacht. Ihr könnt nicht mehr als 10 'Elektrische Aufladungen' ansammeln und könnt nicht mehr als einmal alle 2,5 Sek. eine erhalten. (2.5s Abklingzeit)\nVerkaufspreis:" }
entries[69111] = { ["name"] = "Fänge des Schicksals", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Fänge des Schicksals (1)\nSchmuck\n+4 Intelligenz\nBenutzen: Die nächsten 10 Zauber, die innerhalb von 20 Sek. gewirkt werden, verringern die Kosten Eurer Heilig- und Naturzauber um 1 . Bis zu 10-mal stapelbar. (900ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[69112] = { ["name"] = "Der Hungerleider", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Der Hungerleider (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, Euer Tempo 15 Sek. lang um 23 zu erhöhen. (59s Abklingzeit)\nVerkaufspreis:" }
entries[69113] = { ["name"] = "Apparat von Khaz'goroth", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Apparat von Khaz'goroth (1)\nSchmuck\n+4 Stärke\nAnlegen: Eure kritischen Nahkampftreffer gewähren Euch Titanische Kraft, mit der Ihr diesen Apparat betreiben könnt. Die Titanische Kraft ist bis zu 5-mal stapelbar und hält 30 Sek. lang an.\nBenutzen: Zehrt sämtliche Titanische Kraft auf, um Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft pro angesammelter Titanischer Kraft um 5 zu erhöhen. Hält 15 Sek. lang an. Der Apparat wird immer den höchsten dieser drei Werte auswählen. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[69138] = { ["name"] = "Spinnenseidenspindel", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Spinnenseidenspindel (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Nahkampfangriffe, die Eure Gesundheit unter 35% fallenlassen, verleihen Euch einen Schutzschild, der 30 Sek. lang 16 Schaden absorbiert. Kann nicht öfter als ein Mal pro Minute auftreten. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[69139] = { ["name"] = "Nekromantischer Fokus", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Nekromantischer Fokus (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Erhöht 10 Sek. lang jedes Mal, wenn Ihr regelmäßigen Zauberschaden zufügt, Eure Meisterschaft um 1 . Bis zu 10-mal stapelbar.\nVerkaufspreis:" }
entries[69149] = { ["name"] = "Auge der lodernden Kraft", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Auge der lodernden Kraft (1)\nSchmuck\n+4 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, das am schwersten verletzte nahe Gruppenmitglied um 15 zu heilen. (Procchance: 10%, 45s Abklingzeit)\nVerkaufspreis:" }
entries[69150] = { ["name"] = "Matrixrestabilisator", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Matrixrestabilisator (1)\nSchmuck\n+4 Beweglichkeit\nAnlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, 30 Sek. lang Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft (je nachdem, welcher Wert derzeit am höchsten ist) um 23 zu erhöhen. (Procchance: 20%, 1.75Min. Abklingzeit)\nVerkaufspreis:" }
entries[69167] = { ["name"] = "Gefäß der Beschleunigung", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Gefäß der Beschleunigung (1)\nSchmuck\n+4 Stärke\nAnlegen: Erhöht den kritischen Trefferwert jedes Mal, wenn Ihr einen kritischen Nahkampftreffer erzielt, 20 Sek. lang um 1 . Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[69184] = { ["name"] = "Hinrichtungsaufschub", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Hinrichtungsaufschub (1)\nSchmuck\n+ 6 Ausweichen\nBenutzen: Absorbiert 20% des eintreffenden Schadens, bis zu 54 Schaden insgesamt. Wenn der Effekt endet, erleidet Ihr 10 Sek. lang alle 2 Sek. 8% des absorbierten Schadens. Hält 30 Sek. lang an. (2 Min Abklingzeit)\nBenötigt Rächer des Hyjal\n- Respektvoll\nVerkaufspreis:" }
