entries[69213] = { ["name"] = "Hippogryph des Flammenschutzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Hippogryphen des Flammenschutzes oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hippogryphen des Flammenschutzes feiern den Fall von Ragnaros, dem Herrn des Feuers.\"\nErfolg:\nDie Offensive an der Geschmolzenen Front\nKategorie:\nKataklysmus" }
entries[69214] = { ["name"] = "Aschenweberei", ["text"] = "Questgegenstand\n\"Winzige Spinnen brüten in dem matschigen, gelartigen Sack.\"" }
entries[69215] = { ["name"] = "Anbindepfosten des Kampftrupps", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Einen Anbindepfosten des Kriegstrupps aufzustellen.\n\nGruppen- oder Schlachtzugsmitglieder mit einer Reitfertigkeit von mindestestens 'Unerfahrener Reiter' können den Pfosten benutzen, um ein Zugpferd als Reittier zu beschwören. (30 Min Abklingzeit)" }
