entries[69224] = { ["name"] = "Schwelendes Ei von Millagazor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Reinblut-Feuerfalken beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Reinblut-Feuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Legenden zufolge kann das Reinblutgeschlecht bis zur Erschaffung der Feuerlande zurückverfolgt werden.\"\nBeute von:\nRagnaros\nZone:\nFeuerlande" }
entries[69225] = { ["name"] = "Fangzahn des Wolfs", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kanalisiert den Geist des Wolfsahnen und ruft Lylagar aus seinem Versteck. (15 Sek. Abklingzeit)" }
entries[69226] = { ["name"] = "Teufelsfeuerfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Teufelsfeuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Teufelsfeuer ist schon bei Berührung tödlich. Glücklicherweise kann der Falke die Flammen unterdrücken und seinen Reiter so davor bewahren, in smaragdgrünen Flammen aufzugehen.\"\nErfolg:\nReittierruhm" }
entries[69227] = { ["name"] = "Katzengold", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ein Katzengoldvorkommen zu platzieren.\n\nSpieler können das Vorkommen benutzen, um vorübergehend Gierige Kobolde als Haustiere zu beschwören. (30 Min Abklingzeit)" }
entries[69228] = { ["name"] = "Wilder Raptor", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren wilden Raptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der einstige Begleiter von Kanga dem Wilden, einem gefallenen Trollhelden. Der Name des Raptoren ist unbekannt, denn Kanga sprach nur in der Bärengestalt mit ihm.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[69230] = { ["name"] = "Verderbtes Ei von Millagazor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen verderbten Feuerfalken beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren verderbten Feuerfalken oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Millagazor war ein Feuerfalke, der Ragnaros treu ergeben war. Bisher ist es unbekannt, wie viele von Millagazors Eiern verderbt wurden.\"\nErfolg:\nRuhm des Schlachtzüglers der Feuerlande\nKategorie:\nDungeons & Schlachtzüge" }
